SELECT

FROM console_api_keys
WHERE organization_uuid = #{organizationUUID}

    AND workspace_uuid = #{workspaceUUID}

ORDER BY created_at DESC, external_id DESC

SELECT COUNT(*)
FROM console_api_keys
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND archived_at IS NULL

SELECT EXISTS (
    SELECT 1
    FROM users u
    WHERE u.organization_uuid = #{organizationUUID}
    AND u.uuid = #{userUUID}
    AND u.deleted_at IS NULL
)
